// Shapewall site service worker, generated by scripts/prerender.mjs (the placeholders are filled in at build time).
// Pages: network first, the cached copy when offline. Hashed bundles (/assets/): cache first, they never change.
// Icons, images and share cards: served from cache, refreshed in the background. It never reloads a page.
const VERSION = '__VERSION__'
const PRECACHE = '__PRECACHE__'
const PAGES = '__PAGES__'
const SHELL = 'shapewall-shell-' + VERSION
const RUNTIME = 'shapewall-runtime'
const RUNTIME_MAX = 120

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL)
      .then((cache) => cache.addAll(PRECACHE.map((url) => new Request(url, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys()
      await Promise.all(keys.filter((key) => key.startsWith('shapewall-shell-') && key !== SHELL).map((key) => caches.delete(key)))
      await self.clients.claim()
    })(),
  )
})

async function trim() {
  const cache = await caches.open(RUNTIME)
  const keys = await cache.keys()
  for (let index = 0; index < keys.length - RUNTIME_MAX; index += 1) await cache.delete(keys[index])
}

// A page's cache key: /features.html and /features/ are the same page as /features.
function pageKey(url) {
  let key = url.pathname.replace(/\.html$/, '').replace(/\/+$/, '') || '/'
  if (key === '/index') key = '/'
  return PAGES.includes(key) ? key : null
}

async function navigate(request) {
  const key = pageKey(new URL(request.url))
  try {
    const response = await fetch(request)
    if (key && response.ok && !response.redirected) {
      const copy = response.clone()
      caches
        .open(SHELL)
        .then((cache) => cache.put(key, copy))
        .catch(() => {})
    }
    return response
  } catch {
    const cache = await caches.open(SHELL)
    return (key && (await cache.match(key))) || (await cache.match('/404.html')) || Response.error()
  }
}

async function cacheFirst(request) {
  const hit = await caches.match(request)
  if (hit) return hit
  const response = await fetch(request)
  if (response.ok) {
    const copy = response.clone()
    caches
      .open(RUNTIME)
      .then((cache) => cache.put(request, copy))
      .then(trim)
      .catch(() => {})
  }
  return response
}

async function staleWhileRevalidate(request) {
  const hit = await caches.match(request, { ignoreSearch: true })
  const update = fetch(request).then((response) => {
    if (response.ok) {
      const copy = response.clone()
      caches
        .open(RUNTIME)
        .then((cache) => cache.put(request, copy))
        .then(trim)
        .catch(() => {})
    }
    return response
  })
  if (hit) {
    update.catch(() => {})
    return hit
  }
  return update
}

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET') return
  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return
  if (url.pathname.startsWith('/umami/') || url.pathname === '/sw.js') return
  if (request.mode === 'navigate') event.respondWith(navigate(request))
  else if (url.pathname.startsWith('/assets/')) event.respondWith(cacheFirst(request))
  else if (/^\/(images|og)\/|^\/(icon-|favicon\.|apple-touch-icon|manifest\.webmanifest)/.test(url.pathname)) {
    event.respondWith(staleWhileRevalidate(request))
  }
})
